package com.nova.orders;
import com.nova.auth.User; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="orders") public class OrderRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; @Column(nullable=false,precision=12,scale=2) private BigDecimal totalAmount; @Column(nullable=false) private String status="PENDING_PAYMENT"; @Column(nullable=false,length=100) private String recipientName; @Column(nullable=false,length=30) private String recipientPhone; @Column(nullable=false,length=1000) private String deliveryAddress; @Column(length=254) private String contactEmail; @Column(nullable=false,columnDefinition="text") private String itemsJson; @Column(nullable=false) private Instant createdAt=Instant.now(); protected OrderRecord(){} public OrderRecord(User u,BigDecimal total,String name,String phone,String address,String email,String items){user=u;totalAmount=total;recipientName=name;recipientPhone=phone;deliveryAddress=address;contactEmail=email;itemsJson=items;} public Long getId(){return id;} public void setId(Long id){this.id=id;} public BigDecimal getTotalAmount(){return totalAmount;} public String getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public String getItemsJson(){return itemsJson;} public String getRecipientName(){return recipientName;} public String getRecipientPhone(){return recipientPhone;} public String getDeliveryAddress(){return deliveryAddress;} public String getContactEmail(){return contactEmail;} public void setStatus(String s){status=s;} public User getUser(){return user;} }
